.sheet-close { position: absolute; top: 12px; right: 12px; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--ink-3); transition: background var(--fast), color var(--fast); }
.sheet-close:hover { background: rgba(255, 255, 255, 0.07); color: var(--ink); }
.sheet-head { display: grid; gap: 6px; padding-right: 28px; }
.sheet-layer { display: inline-flex; align-items: center; gap: 8px; font-size: var(--t-label); font-weight: 600; color: var(--ink); }
.sheet-what { font-size: var(--t-label); color: var(--ink-3); max-width: 46ch; }
.sheet-title { font-size: var(--t-read); font-weight: 500; line-height: 1.35; color: var(--ink); text-wrap: balance; }
.sheet-figure { display: flex; align-items: baseline; gap: 12px; }
.sheet-figure .num { font-size: 34px; color: var(--ink); }
.sheet-yoy { font-size: var(--t-body); color: var(--ink-2); }
.sheet-link { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; justify-self: start; }
.zbar { position: relative; height: 30px; }
.zbar-mid { position: absolute; left: 50%; top: 0; height: 12px; width: 1px; background: var(--hair-2); }
.zbar-fill { position: absolute; top: 4px; height: 4px; border-radius: 2px; background: var(--ink); }
.zbar-l, .zbar-r { position: absolute; top: 16px; }
.zbar-l { left: 0; } .zbar-r { right: 0; }
.minibars { display: flex; gap: 22px; align-items: flex-end; }
.minibar { display: grid; gap: 6px; justify-items: center; }
.minibar-n { font-size: var(--t-label); color: var(--ink-2); font-variant-numeric: tabular-nums; }
.minibar-col { width: 26px; height: 96px; display: flex; align-items: flex-end; }
.minibar-col span { width: 100%; height: 100%; background: var(--ink-3); border-radius: 2px 2px 0 0; transform-origin: 50% 100%; }
.minibar[data-on] .minibar-col span { background: var(--ink); }
.minibar[data-on] .minibar-n { color: var(--ink); }
.minibar[data-forecast] .minibar-col span { background: transparent; box-shadow: inset 0 0 0 1px var(--ink-2); }
.sheet-quote { margin: 0; font-size: var(--t-read); line-height: 1.5; color: var(--ink); max-width: 60ch; padding-right: 16px; }
.sheet-facts { margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }
.sheet-facts div { display: grid; gap: 3px; min-width: 0; }
.sheet-facts dd { margin: 0; font-size: 13px; color: var(--ink-2); display: inline-flex; align-items: center; gap: 6px; }
.sheet-ref { letter-spacing: 0.08em; }
.sheet-skel { display: grid; gap: 10px; }
.sheet-skel span { height: 12px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); }
.sheet-skel span:last-child { width: 60%; }

@media (max-width: 760px) {
  .readout { gap: 10px 20px; left: 16px; top: 16px; max-width: calc(100vw - 32px); }
  .readout .num { font-size: 22px; }
  .key { bottom: auto; top: 200px; width: calc(100vw - 32px); left: 16px; }
  .key-values { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 4px; }
  .key-values button { margin: 0; grid-template-columns: auto auto; gap: 6px; border: 1px solid var(--hair); border-radius: 99px; padding: 4px 10px; white-space: nowrap; }
  .key-bar { display: none; }
  .sheet { top: auto; bottom: 140px; }
}

content.content:
1	// Scan: every raw piece of evidence the system holds, at the current checkpoint, as one 3D space.
2	import { Suspense, useEffect, useMemo, useState } from "react";
3	import { Canvas } from "@react-three/fiber";
4	import { useQuery } from "@tanstack/react-query";
5	import { ExternalLink, X } from "lucide-react";
6	import { api } from "@/lib/api";
7	import type { Comment, PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
8	import { CandidateBody, ClusterBody, Funnel, SignalList, ThemeBody } from "../structure/panels";
9	import { AgentPanel, useActivity } from "../structure/AgentPanel";
10	import { PageSwitch } from "@/components/PageSwitch";
11	import { useCheckpoint } from "@/state/checkpoint";
12	import { Scene, TYPE_COLOR, layerOf, studyValue, type Hover } from "./Scene";
13	import { CAR_NAME, MARKET_NAME } from "./layout";
14	import "./scan.css";
15	
16	const fmt = (n: number | undefined | null) => (n == null ? "–" : n.toLocaleString("en-US"));
17	
18	type Dim = "car" | "market" | "channel" | "type" | "engine";
19	const DIMS: { id: Dim; name: string }[] = [
20	  { id: "car", name: "Car" }, { id: "market", name: "Market" }, { id: "channel", name: "Channel" },
21	  { id: "type", name: "Label" }, { id: "engine", name: "Engine" },
22	];
23	function valueName(dim: Dim, v: string | null): string {
24	  if (v == null) return "Unlabelled";
25	  if (dim === "car") return CAR_NAME[v] ?? v;
26	  if (dim === "market") return MARKET_NAME[v] ?? v;
27	  return v;
28	}
29	
30	export function Scan({ mode = "scan" }: { mode?: "scan" | "structure" }) {
31	  const { cp, from, sweepId, position, checkpoints } = useCheckpoint();
32	  const structure = useQuery({ queryKey: ["structure", cp], queryFn: () => api.get<StructurePayload>(`/api/structure?cp=${cp}`),
33	                               staleTime: 30_000, placeholderData: (prev) => prev });
34	  const [hoverKey, setHoverKey] = useState<string | null>(null);
35	  const activity = useActivity();
36	  // when a stage finishes, show its output without a reload
37	  const doneStages = activity.data?.stages.filter((s) => s.status === "completed").map((s) => s.stage).join(",");
38	  useEffect(() => { structure.refetch(); }, [doneStages]); // eslint-disable-line react-hooks/exhaustive-deps
39	  const points = useQuery({ queryKey: ["scan", "points"], queryFn: () => api.get<PointsPayload>("/api/scan/points"), staleTime: Infinity });
40	  const sources = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity });
41	  const [dim, setDim] = useState<Dim>("car");
42	  const [isolate, setIsolate] = useState<Set<number>>(new Set());
43	  const [hover, setHover] = useState<Hover | null>(null);
44	  const [selected, setSelected] = useState<{ sel: Selection; at: [number, number, number] } | null>(null);
45	  const fromPosition = checkpoints?.find((c) => c.id === from)?.position ?? position;
46	
47	  const mask = useMemo(() => {
48	    const n = points.data?.n ?? 0;
49	    const m = new Uint8Array(n).fill(1);
50	    if (!points.data || isolate.size === 0) return m;
51	    const col = points.data.cols[dim];
52	    for (let i = 0; i < n; i++) m[i] = isolate.has(col[i]) ? 1 : 0;
53	    return m;
54	  }, [points.data, dim, isolate]);
55	
56	  useEffect(() => {
57	    const onKey = (e: KeyboardEvent) => {
58	      if (e.key !== "Escape") return;
59	      if (selected) setSelected(null); else setIsolate(new Set());
60	    };
61	    window.addEventListener("keydown", onKey);
62	    return () => window.removeEventListener("keydown", onKey);
63	  }, [selected]);
64	  useEffect(() => { setSelected(null); setHover(null); }, [mode]);
65	
66	  return (
67	    <main className="scan" data-mode={mode} aria-label={mode === "structure" ? "Structure and context at the selected checkpoint" : "Raw evidence at the selected checkpoint"}>
68	      <div className="scan-canvas">
69	        {points.data && (
70	          <Canvas dpr={[1, 2]} camera={{ position: [0, 2.3, 5.3], fov: 40, near: 0.05, far: 60 }}
71	                  raycaster={{ params: { Points: { threshold: 0.018 }, Line: { threshold: 0 }, Mesh: {}, LOD: {}, Sprite: {} } }}
72	                  gl={{ antialias: true, alpha: false }} onCreated={({ gl }) => gl.setClearColor("#000000")}
73	                  onPointerMissed={() => setSelected(null)}>
74	            <Suspense fallback={null}>
75	              <Scene points={points.data} sources={sources.data} mask={mask} position={position} fromPosition={fromPosition}
76	                     sweepId={sweepId} hoverComment={hover?.comment ?? null} locked={selected?.at ?? null} focus={selected ? layerOf(selected.sel) : null}
77	                     onHover={setHover} onSelect={(sel, at) => { setSelected({ sel, at }); setHover(null); }}
78	                     mode={mode} structure={structure.data} selected={selected?.sel ?? null} hoverKey={hoverKey}
79	                     onStructureHover={(h, k) => { setHover(h); setHoverKey(k ?? null); }} pulse={activity.data?.recent} />
80	            </Suspense>
81	          </Canvas>
82	        )}
83	        {points.isPending && <div className="scan-state"><span className="scan-pulse" aria-hidden />Scanning</div>}
84	        {points.isError && <div className="scan-state error">{(points.error as Error).message}</div>}
85	      </div>
86	
87	      {mode === "scan" ? <Readout /> : <Funnel data={structure.data} />}
88	      {mode === "structure" && <AgentPanel />}
89	      <PageSwitch />
90	
91	      {mode === "scan" && points.data && (
92	        <Key points={points.data} position={position} dim={dim} isolate={isolate}
93	             onDim={(d) => { setDim(d); setIsolate(new Set()); }}
94	             onToggle={(v) => setIsolate((s) => { const n = new Set(s); n.has(v) ? n.delete(v) : n.add(v); return n; })}
95	             onClear={() => setIsolate(new Set())} />
96	      )}
97	
98	      {hover && !selected && <HoverCard hover={hover} points={points.data} />}
99	      {selected && <Inspector sel={selected.sel} sales={sources.data?.sales ?? []} onClose={() => setSelected(null)} structure={structure.data}
100	                              cpLabel={(id) => checkpoints?.find((c) => c.id === id)?.label ?? id} />}
101	    </main>
102	  );
103	}
104	
105	/* ------------------------------------------------------------------------------------------- glyphs */
106	type GlyphKind = "comment" | "study" | "option" | "sales" | "research";
107	const GLYPH_COLOR: Record<GlyphKind, string> = {
108	  comment: TYPE_COLOR.comment, study: TYPE_COLOR.study, option: TYPE_COLOR.option, sales: TYPE_COLOR.sales, research: TYPE_COLOR.research,
109	};
110	function Glyph({ kind }: { kind: GlyphKind }) {
111	  const c = "currentColor";
112	  return (
113	    <svg width="14" height="14" viewBox="0 0 14 14" aria-hidden className="glyph" style={{ color: GLYPH_COLOR[kind] }}>
114	      {kind === "comment" && <><circle cx="4" cy="6" r="1.6" fill={c} /><circle cx="9.5" cy="4" r="1.6" fill="none" stroke={c} /><circle cx="8.5" cy="10" r="1.4" fill={c} /></>}
115	      {kind === "study" && <><path d="M2 8h10" stroke={c} strokeOpacity=".35" /><path d="M4 8V4M7 8v4M10 8V3" stroke={c} strokeWidth="1.3" /></>}
116	      {kind === "option" && <>{[2.5, 5.5, 8.5, 11.5].map((x) => <circle key={x} cx={x} cy="7" r="1" fill={c} />)}</>}
117	      {kind === "sales" && <><rect x="2.5" y="6" width="2" height="6" fill={c} /><rect x="6" y="3" width="2" height="9" fill={c} /><rect x="9.5" y="2.5" width="2" height="9.5" fill="none" stroke={c} /></>}
118	      {kind === "research" && <><path d="M1.5 9.5a6 6 0 0 1 11 0" fill="none" stroke={c} strokeDasharray="1.5 1.5" /><circle cx="7" cy="4.2" r="1.4" fill={c} /></>}
119	    </svg>
120	  );
121	}
122	
123	/* ------------------------------------------------------------------------------------------- readout */
124	// One cell per colour in the scene, named and counted. The car rings carry BMW's own data plus cited public research
125	// in the same colour, so their cell gives both: BMW's count large, the public items beneath.
126	function Readout() {
127	  const { current, position } = useCheckpoint();
128	  const src = useQuery({ queryKey: ["scan", "sources"], queryFn: () => api.get<SourcesPayload>("/api/scan/sources?cp=cp2"), staleTime: Infinity }).data;
129	  const s = current?.sources;
130	  const plus = (n: number | undefined) => (position > 1 && n ? <span className="plus">+{fmt(n)}</span> : null);
131	  const research = (ring: ResearchItem["ring"]) => {
132	    const items = (src?.research ?? []).filter((r) => r.ring === ring && (position > 1 || !r.new));
133	    return src ? { n: items.length, nu: items.filter((r) => r.new).length } : undefined;
134	  };
135	  const time = research(null), rating = research("study"), news = research("options"), pub = research("sales");
136	  const cells: { k: GlyphKind; label: string; n: number | undefined; nu?: number; pub?: { label: string; c?: { n: number; nu: number } } }[] = [
137	    { k: "comment", label: "Customer comments", n: s?.feedback.visible, nu: s?.feedback.new },
138	    { k: "research", label: "Web research", n: time?.n, nu: time?.nu },
139	    { k: "study", label: "Customer study", n: src?.study.length, pub: { label: "public ratings", c: rating } },
140	    { k: "option", label: "Equipment options", n: src?.options.length, pub: { label: "product news", c: news } },
141	    { k: "sales", label: "Sales volumes", n: src?.sales.filter((r) => r.units && r.units > 0).length, pub: { label: "public sales", c: pub } },
142	  ];
143	  return (
144	    <dl className="readout" aria-label="Evidence at this checkpoint">
145	      {cells.map((c) => (
146	        <div key={c.label}>
147	          <dt><Glyph kind={c.k} /><span className="label">{c.label}</span></dt>
148	          <dd><span className="num">{fmt(c.n)}</span>{plus(c.nu)}</dd>
149	          {c.pub && (
150	            <dd className="readout-pub">
151	              <i style={{ borderColor: GLYPH_COLOR[c.k] }} aria-hidden />
152	              <span>{fmt(c.pub.c?.n)} {c.pub.label}</span>{plus(c.pub.c?.nu)}
153	            </dd>
154	          )}
155	        </div>
156	      ))}
157	    </dl>
158	  );
159	}
160	
161	/* ------------------------------------------------------------------------------------------- key */
162	function Key(p: { points: PointsPayload; position: number; dim: Dim; isolate: Set<number>; onDim: (d: Dim) => void; onToggle: (v: number) => void; onClear: () => void }) {
163	  const values = p.points.dict[p.dim] as (string | null)[];
164	  const counts = useMemo(() => {
165	    const col = p.points.cols[p.dim], cps = p.points.cols.cp;
166	    const vis = new Array(values.length).fill(0);
167	    for (let i = 0; i < col.length; i++) if (col[i] >= 0 && cps[i] <= p.position) vis[col[i]]++;
168	    return vis as number[];
169	  }, [p.points, p.dim, p.position, values.length]);
170	  const max = Math.max(1, ...counts);
171	  return (
172	    <nav className="key" aria-label="Filter comments">
173	      <div className="key-dims" role="tablist">
174	        {DIMS.map((d) => <button key={d.id} role="tab" aria-selected={p.dim === d.id} onClick={() => p.onDim(d.id)}>{d.name}</button>)}
175	      </div>
176	      <ul className="key-values">
177	        {values.map((v, i) => {
178	          const n = counts[i];
179	          if (!n) return null;
180	          const on = p.isolate.size === 0 || p.isolate.has(i);
181	          return (
182	            <li key={i}>
183	              <button aria-pressed={p.isolate.has(i)} data-dim={on ? undefined : ""} onClick={() => p.onToggle(i)}>
184	                <span className="key-name">{valueName(p.dim, v)}</span>
185	                <span className="key-bar" aria-hidden><span style={{ transform: `scaleX(${n / max})` }} /></span>
186	                <span className="key-n">{fmt(n)}</span>
187	              </button>
188	            </li>
189	          );
190	        })}
191	      </ul>
192	      {p.isolate.size > 0 && <button className="key-clear" onClick={p.onClear}>Show all <span className="label">Esc</span></button>}
193	    </nav>
194	  );
195	}
196	
197	/* ------------------------------------------------------------------------------------------- hover */
198	const useComment = (id: number | null) =>
199	  useQuery({ queryKey: ["comment", id], queryFn: () => api.get<Comment>(`/api/scan/comment/${id}`), staleTime: Infinity, enabled: id != null });
200	
201	function HoverCard({ hover, points }: { hover: Hover; points: PointsPayload | undefined }) {
202	  const id = hover.comment != null && points ? points.cols.id[hover.comment] : null;
203	  const q = useComment(id);
204	  const left = Math.min(hover.x + 16, window.innerWidth - 336), top = Math.min(hover.y + 16, window.innerHeight - 140);
205	  return (
206	    <div className="hovercard" style={{ left, top }} role="tooltip">
207	      {id != null ? (
208	        <>
209	          <p>{q.data?.text ?? " "}</p>
210	          {q.data && (
211	            <div className="hovercard-meta">
212	              <i className={`mark ${hover.acquiredHere ? "new" : "held"}`} aria-hidden />
213	              <span>{CAR_NAME[q.data.car] ?? q.data.car}</span><span>{q.data.country}</span><span>{q.data.channel}</span>
214	            </div>
215	          )}
216	        </>
217	      ) : (
218	        <>
219	          <p>{hover.title}</p>
220	          {hover.sub && <div className="hovercard-meta"><span>{hover.sub}</span></div>}
221	        </>
222	      )}
223	    </div>
224	  );
225	}
226	
227	/* ------------------------------------------------------------------------------------------- inspector */
228	const LAYER: Record<Selection["kind"], { name: string; what: string; glyph: GlyphKind }> = {
229	  comment: { name: "Customer comment", what: "Placed by meaning: comments that say similar things sit close together.", glyph: "comment" },
230	  cluster: { name: "Cluster", what: "Signals from many comments that express the same need. Blue = improve, white = keep.", glyph: "comment" },
231	  theme: { name: "Theme", what: "Related findings grouped by the AI, connected to research, study and options that confirm or contradict them.", glyph: "research" },
232	  candidate: { name: "Potential requirement", what: "Drafted by the AI from the theme and its evidence. A proposal — the PM decides.", glyph: "sales" },
233	  study: { name: "Customer study 2025", what: "Tick length: how far this topic is rated above or below this car's average.", glyph: "study" },
234	  option: { name: "Equipment option", what: "Today's car, from the German price list.", glyph: "option" },
235	  sales: { name: "BMW sales volume", what: "BMW-internal figures, stylized (Q-015). Outline = 2030 forecast.", glyph: "sales" },
236	  research: { name: "Web research", what: "Cited source, placed on the outer ring by publication date.", glyph: "research" },
237	};
238	
239	const PUBLIC_LAYER: Record<"sales" | "study" | "options", { name: string; what: string; glyph: GlyphKind }> = {
240	  sales: { name: "Public sales figure", what: "Cited, published figure for this car. Dots and rings sit beside BMW's own bars, never mixed with them.", glyph: "sales" },
241	  study: { name: "Public rating", what: "Published review, award or study result about this car.", glyph: "study" },
242	  options: { name: "Product news", what: "Published news about this car's equipment, prices or availability.", glyph: "option" },
243	};
244	
245	function Inspector({ sel, sales, onClose, cpLabel, structure }: { sel: Selection; sales: SourcesPayload["sales"]; onClose: () => void; cpLabel: (id: string) => string; structure?: StructurePayload }) {
246	  const L = sel.kind === "research" && sel.item.ring ? PUBLIC_LAYER[sel.item.ring] : LAYER[sel.kind];
247	  return (
248	    <aside className="sheet" aria-label={L.name}>
249	      <button className="sheet-close" onClick={onClose} aria-label="Close"><X size={16} /></button>
250	      <header className="sheet-head">
251	        <span className="sheet-layer"><Glyph kind={L.glyph} />{L.name}</span>
252	        <p className="sheet-what">{L.what}</p>
253	      </header>
254	      {sel.kind === "comment" && <><CommentBody id={sel.id} cpLabel={cpLabel} /><SignalList sourceId={sel.id} /></>}
255	      {sel.kind === "cluster" && <ClusterBody k={sel.key} data={structure} />}
256	      {sel.kind === "theme" && <ThemeBody k={sel.key} />}
257	      {sel.kind === "candidate" && <CandidateBody id={sel.id} data={structure} />}
258	      {sel.kind === "study" && <StudyBody s={sel.item} />}
259	      {sel.kind === "option" && (
260	        <>
261	          <h2 className="sheet-title">{sel.item.name ?? sel.item.code}</h2>
262	          <Facts rows={[["Car", CAR_NAME[sel.item.car] ?? sel.item.car], ["Category", sel.item.category], ["Availability", sel.item.availability],
263	                        ["Package", sel.item.package], ["Option code", sel.item.code]]} />
264	        </>
265	      )}
266	      {sel.kind === "sales" && <SalesBody row={sel.item} all={sales} />}
267	      {sel.kind === "research" && (
268	        <>
269	          <h2 className="sheet-title">{sel.item.headline}</h2>
270	          {(sel.item.value != null || sel.item.yoy != null) && (
271	            <div className="sheet-figure">
272	              {sel.item.value != null && <span className="num">{sel.item.value.toLocaleString("en-US")}{sel.item.unit === "pct" ? "%" : ""}</span>}
273	              {sel.item.yoy != null && <span className="sheet-yoy">{sel.item.yoy > 0 ? "+" : ""}{sel.item.yoy}% YoY</span>}
274	            </div>
275	          )}
276	          <Facts rows={[["Published", sel.item.published_at ?? "undated"], ["Known from", sel.item.new ? "JUL 26" : "JAN 26"],
277	                        ["About", sel.item.entity], ["Region", sel.item.region], ["Trust", sel.item.tier]]} />
278	          {sel.item.url && <a className="sheet-link" href={sel.item.url} target="_blank" rel="noreferrer">Open source <ExternalLink size={13} /></a>}
279	          <SignalList sourceId={sel.item.id} />
280	        </>
281	      )}
282	    </aside>
283	  );
284	}
285	
286	function Facts({ rows }: { rows: [string, string | null | undefined][] }) {
287	  return (
288	    <dl className="sheet-facts">
289	      {rows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt className="label">{k}</dt><dd>{v}</dd></div>)}
290	    </dl>
291	  );
292	}
293	
294	function CommentBody({ id, cpLabel }: { id: number; cpLabel: (id: string) => string }) {
295	  const q = useComment(id);
296	  const c = q.data;
297	  if (!c) return <div className="sheet-skel" aria-hidden><span /><span /><span /></div>;
298	  const label = c.bmw_labels?.[0];
299	  return (
300	    <>
301	      <blockquote className="sheet-quote">{c.text}</blockquote>
302	      <Facts rows={[["Car", CAR_NAME[c.car] ?? c.car],
303	                    ["Market", `${MARKET_NAME[c.market] ?? c.market}${c.country && c.country !== c.market ? ` · ${c.country}` : ""}`],
304	                    ["Channel", c.channel], ["Engine", c.engine],
305	                    ["BMW label", `${label?.feedback_type ?? "Unlabelled"}${label?.vfc_level2 && label.vfc_level2 !== "no_class_found" ? ` · ${label.vfc_level2}` : ""}`],
306	                    ["Acquired", cpLabel(c.checkpoint)], ["ID", c.external_id]]} />
307	    </>
308	  );
309	}
310	
311	function StudyBody({ s }: { s: Extract<Selection, { kind: "study" }>["item"] }) {
312	  const z = Math.max(-2.5, Math.min(2.5, s.z ?? 0));
313	  return (
314	    <>
315	      <h2 className="sheet-title">{s.item}</h2>
316	      <div className="sheet-figure"><span className="num">{studyValue(s)}</span></div>
317	      <div className="zbar" role="img" aria-label={`${z >= 0 ? "Above" : "Below"} this car's average by ${Math.abs(z).toFixed(1)} standard deviations`}>
318	        <span className="zbar-mid" />
