1	// The scan volume (react-three-fiber). One shader decides, per contact, whether the current sweep has acquired it.
2	// Each raw data type has its own colour (TYPE_COLOR); track state is the mark's shape: held contacts (known at the
3	// earlier checkpoint) are dots, contacts this sweep acquired are rings. The flare as the sweep passes, hover and the
4	// lock reticle turn white; blue is the sweep blade itself.
5	// The same rule drives the comments and the dated research on the time ring. Every ring element can be opened.
6	// Opening one focuses its layer (the cluster or one ring): that layer rises, the others sink and fade out of the way.
7	import { useEffect, useMemo, useRef, type ReactNode } from "react";
8	import { useFrame, useThree, type ThreeEvent } from "@react-three/fiber";
9	import { Billboard, Html, OrbitControls } from "@react-three/drei";
10	import * as THREE from "three";
11	import type { PointsPayload, ResearchItem, Selection, SourcesPayload, StructurePayload } from "@/lib/types";
12	import { StructureLayer } from "../structure/StructureLayer";
13	import { ClassifyPulse } from "../structure/ClassifyPulse";
14	import { CARS, CAR_NAME, LINES, LINE_CODES, MARKET_NAME, R, SWEEP_START, TAU, TIME_START, lineSector, optionLayout, polar, sector, studyLayout, timeAngle } from "./layout";
15	
16	const VERT = /* glsl */ `
17	attribute float aCp; attribute float aSel; attribute float aAz; attribute float aSize; attribute float aIdx;
18	attribute vec3 aTarget; attribute float aClustered;
19	uniform float uCp, uFrom, uSweep, uStart, uScale, uHover, uDim, uMorph;
20	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
21	const float TAU = 6.2831853;
22	void main() {
23	  float lo = min(uCp, uFrom), hi = max(uCp, uFrom);
24	  float d = mod(aAz - uStart + 2.0 * TAU, TAU) / TAU;
25	  float passed = step(d, uSweep);
26	  float vis = aCp <= lo ? 1.0 : (aCp <= hi ? (uCp > uFrom ? passed : 1.0 - passed) : 0.0);
27	  vFlare = (uCp > uFrom && aCp > lo && aCp <= hi) ? passed * exp(-max(uSweep - d, 0.0) * 14.0) * (1.0 - pow(uSweep, 12.0)) : 0.0;
28	  vRing = abs(aCp - uCp) < 0.5 ? 1.0 : 0.0;          // acquired by the current sweep
29	  vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
30	  vec3 pp = mix(position, aTarget, uMorph);            // page 2: comments fly into their cluster
31	  vec4 mv = modelViewMatrix * vec4(pp, 1.0);
32	  float depth = smoothstep(3.2, 7.5, -mv.z);           // far contacts recede
33	  vAlpha = vis * mix(uDim, 1.0, aSel) * mix(0.95, 0.4, depth) * mix(1.0, mix(0.08, 0.4, aClustered), uMorph);
34	  gl_Position = projectionMatrix * mv;
35	  gl_PointSize = aSize * uScale * (1.0 + vRing * 0.25 + vFlare * 2.0 + vHov * 2.2) / -mv.z;
36	}`;
37	const FRAG = /* glsl */ `
38	uniform vec3 uColor; uniform float uFade;
39	varying float vAlpha; varying float vRing; varying float vFlare; varying float vHov;
40	void main() {
41	  float r = length(gl_PointCoord - 0.5);
42	  if (r > 0.5) discard;
43	  float dot = smoothstep(0.5, 0.3, r);
44	  float ring = smoothstep(0.5, 0.42, r) * smoothstep(0.24, 0.32, r);
45	  float a = mix(dot, ring, vRing * (1.0 - vFlare));
46	  vec3 col = mix(uColor, vec3(1.0), max(vFlare, vHov));
47	  gl_FragColor = vec4(col, min(1.0, vAlpha + vHov) * a * uFade);
48	}`;
