53	function contactMaterial(scale: number, color: string) {
54	  return new THREE.ShaderMaterial({
55	    vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
56	    uniforms: {
57	      uCp: { value: 2 }, uFrom: { value: 2 }, uSweep: { value: 1 }, uStart: { value: SWEEP_START },
58	      uScale: { value: scale }, uHover: { value: -1 }, uDim: { value: 0.06 }, uFade: { value: 1 }, uMorph: { value: 0 },
59	      uColor: { value: new THREE.Color(color) },
60	    },
61	  });
62	}
