64	function attrGeometry(pos: Float32Array, attrs: Record<string, Float32Array>) {
65	  const g = new THREE.BufferGeometry();
66	  g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
67	  for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
68	  g.computeBoundingSphere();
69	  return g;
70	}
