72	/* ------------------------------------------------------------------------------------------- focus layers */
73	// One layer per raw data type: the comment cluster and the four rings. Public research sits on its car's ring.
74	export type LayerId = "comment" | "research" | "study" | "option" | "sales";
75	export const layerOf = (s: Selection): LayerId | null =>
76	  s.kind === "cluster" || s.kind === "theme" || s.kind === "candidate" ? null
77	    : s.kind !== "research" ? s.kind : s.item.ring === "options" ? "option" : (s.item.ring ?? "research");
78	
79	const LIFT = 0.12, SINK = -0.5, FADE = 0.08;
80	const ORDER: LayerId[] = ["comment", "research", "study", "option", "sales"]; // inside out
81	const RISE = 0.85, FALL = 0.7, STAGGER = 0.07;                                 // seconds
82	const easeOutBack = (t: number) => 1 + 2.2 * Math.pow(t - 1, 3) + 1.2 * Math.pow(t - 1, 2);
83	const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
84	const easeOut = (t: number) => 1 - Math.pow(1 - t, 3);
85	
86	// Focus choreography: the chosen layer springs up (slight overshoot) with a soft scale pulse; the others sink and
87	// fade in a ripple outward from it. Releasing focus ripples back the same way. Under reduced motion the layers still
88	// glide (the move is what shows which layer the item belongs to), just without overshoot, pulse or ripple.
89	function Layer({ id, focus, children }: { id: LayerId; focus: LayerId | null; children: ReactNode }) {
90	  const ref = useRef<THREE.Group>(null);
91	  const st = useRef({ y: 0, a: 1, fy: 0, fa: 1, t0: -1, delay: 0, rising: false, focus: null as LayerId | null });
92	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
93	  useFrame(({ clock }) => {
94	    const g = ref.current;
95	    if (!g) return;
96	    const s = st.current, now = clock.elapsedTime;
97	    if (s.focus !== focus) {                 // new target: start a tween from wherever the layer is now
98	      const anchor = focus ?? s.focus;       // ripple out from the layer gaining (or losing) focus
99	      s.focus = focus;
100	      s.fy = s.y; s.fa = s.a; s.t0 = now; s.rising = focus === id;
101	      s.delay = reduced || anchor == null || s.rising ? 0 : Math.abs(ORDER.indexOf(id) - ORDER.indexOf(anchor)) * STAGGER;
102	    }
103	    const [ty, ta] = focus == null ? [0, 1] : focus === id ? [LIFT, 1] : [SINK, FADE];
104	    let p = 1;
105	    if (s.t0 >= 0) p = Math.min(1, Math.max(0, (now - s.t0 - s.delay) / (s.rising ? RISE : FALL)));
106	    if (p >= 1 && s.y === ty && s.a === ta && g.userData.settled === children) return;
107	    s.y = s.fy + (ty - s.fy) * (s.rising && !reduced ? easeOutBack(p) : easeInOut(p));
108	    s.a = s.fa + (ta - s.fa) * easeOut(p);
109	    if (p >= 1) { s.y = ty; s.a = ta; }
110	    g.position.y = s.y;
111	    g.scale.setScalar(s.rising && !reduced ? 1 + 0.04 * Math.sin(Math.PI * p) : 1);
112	    g.userData.settled = children;
113	    g.traverse((o) => {
114	      const mat = (o as THREE.Mesh).material;
115	      if (!mat) return;
116	      for (const m of Array.isArray(mat) ? mat : [mat]) {
117	        if (m instanceof THREE.ShaderMaterial) { if (m.uniforms.uFade) m.uniforms.uFade.value = s.a; continue; }
118	        m.userData.baseOpacity ??= m.opacity;
119	        m.opacity = m.userData.baseOpacity * s.a;
120	      }
121	    });
122	  });
123	  return <group ref={ref}>{children}</group>;
124	}
