126	/* ------------------------------------------------------------------------------------------- sweep clock */
127	function useSweep(mats: THREE.ShaderMaterial[], position: number, fromPosition: number, sweepId: number, onAngle: (a: number | null) => void) {
128	  const start = useRef<number | null>(null);
129	  const reduced = useMemo(() => window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false, []);
130	  useEffect(() => {
131	    for (const m of mats) { m.uniforms.uCp.value = position; m.uniforms.uFrom.value = fromPosition; m.uniforms.uSweep.value = reduced ? 1 : 0; }
132	    start.current = reduced || position === fromPosition ? null : performance.now();
133	  }, [sweepId]); // eslint-disable-line react-hooks/exhaustive-deps
134	  useFrame(() => {
135	    if (start.current == null) { onAngle(null); return; }
136	    const t = Math.min(1, (performance.now() - start.current) / 2400);
137	    const e = 1 - Math.pow(1 - t, 3);
138	    for (const m of mats) m.uniforms.uSweep.value = e;
139	    onAngle(t < 1 ? SWEEP_START + e * TAU : null);
140	    if (t >= 1) { start.current = null; for (const m of mats) m.uniforms.uFrom.value = m.uniforms.uCp.value; }
141	  });
142	}
