144	/* ------------------------------------------------------------------------------------------- camera fit */
145	function CameraFit() {
146	  const { camera, size } = useThree();
147	  useEffect(() => {
148	    const cam = camera as THREE.PerspectiveCamera;
149	    const aspect = size.width / size.height;
150	    cam.fov = aspect < 1 ? 58 : 40;
151	    const fit = (R.labels + 0.3) / (Math.tan(THREE.MathUtils.degToRad(cam.fov / 2)) * aspect);
152	    cam.position.setLength(Math.max(aspect < 1 ? 6 : 5.6, fit));
153	    cam.updateProjectionMatrix();
154	  }, [camera, size.width, size.height]);
155	  return null;
156	}
