184	export function Scene(p: SceneProps) {
185	  const { gl } = useThree();
186	  const dpr = gl.getPixelRatio();
187	  const commentMat = useMemo(() => contactMaterial(15 * dpr, TYPE_COLOR.comment), [dpr]);
188	  const researchMat = useMemo(() => contactMaterial(19 * dpr, TYPE_COLOR.research), [dpr]);
189	  const sweepRef = useRef<THREE.Group>(null);
190	  const setCursor = (on: boolean) => { gl.domElement.style.cursor = on ? "pointer" : ""; };
191	
192	  /* comments */
193	  const comments = useMemo(() => {
194	    const c = p.points.cols, n = p.points.n;
195	    const pos = new Float32Array(n * 3), cp = new Float32Array(n), az = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
196	    for (let i = 0; i < n; i++) {
197	      pos[i * 3] = c.x[i]; pos[i * 3 + 1] = c.y[i] * 0.72; pos[i * 3 + 2] = c.z[i];
198	      cp[i] = c.cp[i]; az[i] = Math.atan2(c.z[i], c.x[i]); idx[i] = i;
199	      size[i] = 0.85 + Math.min(0.8, Math.sqrt(c.len[i] / 300));
200	    }
201	    return attrGeometry(pos, { aCp: cp, aAz: az, aSize: size, aIdx: idx, aSel: new Float32Array(n).fill(1) });
202	  }, [p.points]);
203	  useEffect(() => {
204	    const a = comments.getAttribute("aSel") as THREE.BufferAttribute;
205	    for (let i = 0; i < p.mask.length; i++) a.setX(i, p.mask[i]);
206	    a.needsUpdate = true;
207	  }, [comments, p.mask]);
208	  useEffect(() => { commentMat.uniforms.uHover.value = p.hoverComment ?? -1; }, [commentMat, p.hoverComment]);
209	
210	  /* page 2 morph: each comment's target is its cluster centre (pulled in tight); unclustered comments stay and dim */
211	  useEffect(() => {
212	    const n = p.points.n, src = comments.getAttribute("position") as THREE.BufferAttribute;
213	    const target = new Float32Array(n * 3), clustered = new Float32Array(n);
214	    const st = p.structure;
215	    const at = new Map<number, number>();
216	    if (st?.ready) st.member.ids.forEach((id, i) => at.set(id, st.member.cluster[i]));
217	    for (let i = 0; i < n; i++) {
218	      const x = src.getX(i), y = src.getY(i), z = src.getZ(i);
219	      const ci = at.get(p.points.cols.id[i]);
220	      const c = ci != null && ci >= 0 ? st!.clusters[ci] : null;
221	      if (c && !c.tail) {
222	        target.set([c.x + (x - c.x) * 0.07, c.y + (y - c.y) * 0.07, c.z + (z - c.z) * 0.07], i * 3);
223	        clustered[i] = 1;
224	      } else target.set([x, y, z], i * 3);
225	    }
226	    comments.setAttribute("aTarget", new THREE.BufferAttribute(target, 3));
227	    comments.setAttribute("aClustered", new THREE.BufferAttribute(clustered, 1));
228	  }, [comments, p.points, p.structure]);
229	  const morph = useRef(0);
230	  useFrame((_, dt) => {
