232	    if (morph.current === goal) return;
233	    const step = dt / 1.6;
234	    morph.current = goal > morph.current ? Math.min(goal, morph.current + step) : Math.max(goal, morph.current - step);
235	    const t = morph.current;
236	    commentMat.uniforms.uMorph.value = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
237	  });
238	
239	  /* research on the time ring */
240	  const research = useMemo(() => {
