398	        research: <><points geometry={research.geom} material={researchMat} {...onResearch} />{reticle("research")}</>,
399	        study: <><points geometry={carRings.study.geom} material={studyMat} {...carRingHandlers(carRings.study, "Public rating")} />{reticle("study")}</>,
400	        option: <><points geometry={carRings.options.geom} material={optionMat} {...carRingHandlers(carRings.options, "Product news")} />{reticle("option")}</>,
401	        sales: (
402	          <>
403	            <points geometry={carRings.sales.geom} material={salesMat} {...carRingHandlers(carRings.sales, "Public sales")} />
404	            <lineSegments geometry={carRings.sales.sticks[0]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>
405	            {p.position >= 2 && <lineSegments geometry={carRings.sales.sticks[1]}><lineBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.45} /></lineSegments>}
406	            {reticle("sales")}
407	          </>
408	        ),
409	      }} />
410	      <group ref={sweepRef} visible={false}><SweepBlade /></group>
411	      {p.structure?.ready && (
412	        <StructureLayer data={p.structure} morph={morph} dpr={dpr} selected={p.selected ?? null} hoverKey={p.hoverKey ?? null}
413	                        ends={ends} onHover={p.onStructureHover ?? (() => {})} onSelect={p.onSelect} setCursor={setCursor} />
414	      )}
415	      {p.mode === "structure" && p.locked && p.focus == null && <Reticle at={p.locked} />}
416	      <ClassifyPulse ids={p.pulse} posOf={posOf} dpr={dpr} />
417	    </>
418	  );
419	}
420	
421	/* ------------------------------------------------------------------------------------------- sweep + lock */
422	function SweepBlade() {
423	  const mat = useMemo(() => new THREE.ShaderMaterial({
424	    transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
425	    vertexShader: "varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
426	    fragmentShader: "varying vec2 vUv; void main(){ float a = (1.0 - vUv.x * 0.7) * (1.0 - abs(vUv.y - 0.5) * 2.0); gl_FragColor = vec4(0.18, 0.45, 0.95, 0.32 * a); }",
427	  }), []);
428	  return (
429	    <>
430	      <mesh material={mat} position={[(R.sales + 0.1) / 2, 0, 0]}><planeGeometry args={[R.sales + 0.1, 1.4]} /></mesh>
431	      <mesh position={[(R.sales + 0.1) / 2, 0, 0]}><boxGeometry args={[R.sales + 0.1, 0.004, 0.004]} /><meshBasicMaterial color="#4d94ff" /></mesh>
432	    </>
433	  );
434	}
435	
436	function Reticle({ at }: { at: [number, number, number] }) {
437	  const ref = useRef<THREE.Group>(null);
438	  useFrame(({ clock }) => { if (ref.current) ref.current.rotation.z = clock.elapsedTime * 0.8; });
439	  return (
440	    <Billboard position={at}>
441	      <group ref={ref}>
442	        {[0, 1, 2, 3].map((k) => (
443	          <mesh key={k} rotation={[0, 0, (k * Math.PI) / 2]}>
444	            <ringGeometry args={[0.045, 0.052, 16, 1, -0.45, 0.9]} />
445	            <meshBasicMaterial color="#ffffff" transparent opacity={0.95} depthTest={false} />
446	          </mesh>
447	        ))}
448	      </group>
449	    </Billboard>
450	  );
451	}
452	
453	/* ------------------------------------------------------------------------------------------- source rings */
454	function ringPoints(r: number, a0 = 0, a1 = TAU, seg = 256) {
455	  const pts: THREE.Vector3[] = [];
456	  for (let i = 0; i <= seg; i++) { const a = a0 + ((a1 - a0) * i) / seg; pts.push(new THREE.Vector3(...polar(r, a))); }
457	  return new THREE.BufferGeometry().setFromPoints(pts);
458	}
459	
460	const RING_BEARING = Math.PI / 2; // the gap between the 7 Series and 1 Series sectors faces the viewer
461	const RINGS: Record<Exclude<LayerId, "comment">, { r: number; name: string; color: string }> = {
462	  research: { r: R.time, name: "Research", color: TYPE_COLOR.research }, study: { r: R.study, name: "Study", color: TYPE_COLOR.study },
463	  option: { r: R.options, name: "Options", color: TYPE_COLOR.option }, sales: { r: R.sales, name: "Sales", color: TYPE_COLOR.sales },
464	};
465	
466	function Rings({ sources, focus, slots, onHover, onSelect, setCursor }: {
467	  sources: SourcesPayload | undefined;
468	  focus: LayerId | null;
469	  slots: Record<Exclude<LayerId, "comment">, ReactNode>;
470	  onHover: (h: Hover | null) => void;
471	  onSelect: (s: Selection, at: [number, number, number]) => void;
472	  setCursor: (on: boolean) => void;
473	}) {
474	  // sector guides per ring, each ring with its own material so it can fade on its own
475	  const lines = useMemo(() => {
476	    const guides = (r: number) => {
477	      const guide = new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.1 });
478	      return CARS.map((car) => new THREE.Line(ringPoints(r, ...sector(car), 64), guide));
479	    };
480	    const time = new THREE.Line(ringPoints(R.time, TIME_START - 0.12, TIME_START + (300 / 360) * TAU, 360),
481	      new THREE.LineDashedMaterial({ color: "#ffffff", transparent: true, opacity: 0.22, dashSize: 0.02, gapSize: 0.025 }));
482	    time.computeLineDistances();
483	    return { research: [time], study: guides(R.study), option: guides(R.options), sales: guides(R.sales) };
484	  }, []);
485	
486	  // a bracket just outside the sales ring marking the China long-wheelbase part of the 5 Series sector
487	  const lwbArc = useMemo(() => new THREE.Line(ringPoints(R.sales + 0.08, ...sector("G68"), 32),
488	    new THREE.LineBasicMaterial({ color: "#ffffff", transparent: true, opacity: 0.35 })), []);
489	
490	  // study: a radial tick per item (outward = above this car × market's average item, inward = below); the tip is pickable
491	  const study = useMemo(() => {
492	    const seg: number[] = [], tips: number[] = [], items: NonNullable<typeof sources>["study"] = [];
493	    for (const { item, base, tip } of studyLayout(sources?.study ?? [])) {
494	      seg.push(...base, ...tip); tips.push(...tip); items.push(item);
495	    }
496	    return {
497	      items,
498	      lines: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(seg, 3)),
499	      tips: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(tips, 3)),
500	    };
501	  }, [sources]);
502	
503	  // options: one dot per equipment option of today's car
504	  const options = useMemo(() => {
505	    const v: number[] = [], items: NonNullable<typeof sources>["options"] = [];
506	    for (const { item, at } of optionLayout(sources?.options ?? [])) { v.push(...at); items.push(item); }
507	    return { items, geom: new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3)) };
508	  }, [sources]);
509	
510	  // sales: one bar per car × market × year; the 2030 forecast is an outline
511	  const bars = useMemo(() => {
512	    const rows = (sources?.sales ?? []).filter((s) => s.units && s.units > 0);
513	    const byCar = new Map<string, typeof rows>();
514	    for (const s of rows) byCar.set(s.car, [...(byCar.get(s.car) ?? []), s]);
515	    const out: { row: (typeof rows)[number]; pos: [number, number, number]; rot: number; h: number }[] = [];
516	    for (const [car, items] of byCar) {
517	      const [a0, a1] = sector(car);
518	      items.forEach((s, i) => {
519	        const a = a0 + ((a1 - a0) * (i + 0.5)) / items.length;
520	        const h = Math.max(0.01, (s.units! / 120000) * 0.3);
521	        out.push({ row: s, pos: polar(R.sales, a, h / 2), rot: -a, h });
522	      });
523	    }
524	    return out;
525	  }, [sources]);
526	
527	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) =>
528	    e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
529	  const pos = (g: THREE.BufferGeometry, i: number): [number, number, number] => {
530	    const a = g.getAttribute("position");
531	    return [a.getX(i), a.getY(i), a.getZ(i)];
532	  };
533	  const hover = (e: ThreeEvent<PointerEvent>, title: string, sub: string) => {
534	    e.stopPropagation(); setCursor(true); onHover({ title, sub, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY });
535	  };
536	  const out = () => { setCursor(false); onHover(null); };
537	
538	  const dim = (id: LayerId) => (focus != null && focus !== id ? "" : undefined);
539	  const ringName = (id: Exclude<LayerId, "comment">) => (
540	    <Html position={polar(RINGS[id].r, RING_BEARING, 0.02)} center zIndexRange={[10, 0]}>
541	      <div className="ring-name" data-dim={dim(id)}><i style={{ background: RINGS[id].color }} />{RINGS[id].name}</div>
542	    </Html>
543	  );
544	  const guides = (id: Exclude<LayerId, "comment">) => lines[id].map((l, i) => <primitive key={i} object={l} />);
545	
546	  return (
547	    <>
548	      <Layer id="research" focus={focus}>
549	        {guides("research")}
550	        {slots.research}
551	        {ringName("research")}
552	        {[["JUL 25", "2025-07-01"], ["JAN 26", "2026-01-31"], ["JUL 26", "2026-07-31"]].map(([t, d]) => (
553	          <Html key={t} position={polar(R.time, timeAngle(d), 0.16)} center zIndexRange={[10, 0]}>
554	            <div className="time-label" data-dim={dim("research")}>{t}</div>
555	          </Html>
556	        ))}
557	      </Layer>
558	      <Layer id="study" focus={focus}>
559	        {guides("study")}
560	        <lineSegments geometry={study.lines}><lineBasicMaterial color={TYPE_COLOR.study} transparent opacity={0.75} /></lineSegments>
561	        <points geometry={study.tips}
562	                onPointerMove={(e) => { const i = pick(e); if (i != null) { const s = study.items[i]; hover(e, s.item, `Study · ${CAR_NAME[s.car]} · ${MARKET_NAME[s.market]} · ${studyValue(s)}`); } }}
563	                onPointerOut={out}
564	                onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "study", item: study.items[i] }, pos(study.tips, i)); } }}>
565	          <pointsMaterial color={TYPE_COLOR.study} size={0.016} transparent opacity={0.9} />
566	        </points>
567	        {slots.study}
568	        {ringName("study")}
569	      </Layer>
570	      <Layer id="option" focus={focus}>
571	        {guides("option")}
572	        <points geometry={options.geom}
573	                onPointerMove={(e) => { const i = pick(e); if (i != null) { const o = options.items[i]; hover(e, o.name ?? o.code ?? "Option", `Option · ${CAR_NAME[o.car]} · ${o.availability ?? ""}`); } }}
574	                onPointerOut={out}
575	                onClick={(e) => { const i = pick(e); if (i != null) { e.stopPropagation(); onSelect({ kind: "option", item: options.items[i] }, pos(options.geom, i)); } }}>
576	          <pointsMaterial color={TYPE_COLOR.option} size={0.014} transparent opacity={0.85} />
577	        </points>
578	        {slots.option}
579	        {ringName("option")}
580	      </Layer>
581	      <Layer id="sales" focus={focus}>
582	        {guides("sales")}
583	        {bars.map((b, i) => (
584	          <mesh key={i} position={b.pos} rotation={[0, b.rot, 0]}
585	                onPointerMove={(e) => hover(e, `${(b.row.units ?? 0).toLocaleString("en-US")} cars`, `Sales · ${CAR_NAME[b.row.car]} · ${MARKET_NAME[b.row.market]} · ${b.row.year}${b.row.is_forecast ? " forecast" : ""}`)}
586	                onPointerOut={out}
587	                onClick={(e) => { e.stopPropagation(); onSelect({ kind: "sales", item: b.row }, [b.pos[0], b.h, b.pos[2]]); }}>
588	            <boxGeometry args={[0.014, b.h, 0.014]} />
589	            {b.row.is_forecast ? <meshBasicMaterial color={TYPE_COLOR.sales} wireframe transparent opacity={0.6} /> : <meshBasicMaterial color={TYPE_COLOR.sales} transparent opacity={0.85} />}
590	          </mesh>
591	        ))}
592	        <primitive object={lwbArc} />
593	        <Html position={polar(R.sales + 0.17, (sector("G68")[0] + sector("G68")[1]) / 2, 0.02)} center zIndexRange={[10, 0]}>
594	          <div className="ring-sub" data-dim={dim("sales")}>LWB · China</div>
595	        </Html>
596	        {slots.sales}
597	        {ringName("sales")}
598	      </Layer>
599	      {LINES.map((line) => {
600	        const [a0, a1] = lineSector(line);
601	        return (
602	          <Html key={line} position={polar(R.labels, (a0 + a1) / 2, 0.18)} center zIndexRange={[10, 0]}>
603	            <div className="ring-label"><b>{CAR_NAME[line]}</b><span>{LINE_CODES[line]}</span></div>
604	          </Html>
605	        );
606	      })}
607	    </>
608	  );
609	}
