  --sweep-curve: cubic-bezier(0.33, 1, 0.68, 1);   /* ease-out cubic, the 3D sweep's curve */
  position: fixed; right: var(--edge); bottom: calc(var(--edge) + env(safe-area-inset-bottom, 0px)); z-index: 20;
  width: 300px; display: grid; gap: 12px;
}
.sweepctl-top { display: grid; gap: 3px; }
.sweepctl-title { font-size: var(--t-label); font-weight: 600; color: var(--ink); }

