                  data-state={id === cp ? "active" : i < at ? "built" : "idle"} data-end={frac(cutoff(id)) > 0.9 ? "" : undefined}
                  style={{ left: `${frac(cutoff(id)) * 100}%` }} onClick={() => setCp(id)}>
