.sweepctl-hand path { fill: var(--sweep-wash); }
.sweepctl-hand line { stroke: var(--sweep-hi); stroke-width: 1.25; stroke-linecap: round; }
.sweepctl-hub { fill: var(--ink-3); }

.sweepctl-node { cursor: pointer; }
.sweepctl-hit { fill: transparent; }
.sweepctl-dot { fill: var(--void); stroke: var(--ink-3); stroke-width: 1; transition: fill var(--med) var(--ease), stroke var(--med) var(--ease); }
.sweepctl-halo { fill: var(--sweep-wash); opacity: 0; transition: opacity var(--med) var(--ease); }
.sweepctl-node:hover .sweepctl-dot { stroke: var(--ink); }
.sweepctl-node[data-state="built"] .sweepctl-dot { fill: var(--ink); stroke: var(--ink); }
.sweepctl-node[data-state="active"] .sweepctl-dot { fill: var(--sweep-hi); stroke: var(--sweep-hi); }
.sweepctl-node[data-state="active"] .sweepctl-halo { opacity: 1; }

.sweepctl-side { display: grid; gap: 8px; justify-items: start; }
.sweepctl-head { display: flex; gap: 10px; align-items: baseline; }
.sweepctl-keys { letter-spacing: 0.12em; }
.sweepctl-tabs { display: flex; gap: 14px; }
.sweepctl-tabs button {
  font-size: var(--t-label); font-weight: 600; letter-spacing: 0.08em; color: var(--ink-3);
  padding: 3px 0; border-bottom: 1px solid transparent; transition: color var(--fast), border-color var(--fast);
}
.sweepctl-tabs button:hover { color: var(--ink-2); }
.sweepctl-tabs button[aria-checked="true"] { color: var(--ink); border-bottom-color: var(--sweep-hi); }
.sweepctl-counts { margin: 4px 0 0; display: grid; gap: 7px; }
.sweepctl-counts div { display: flex; align-items: center; gap: 8px; }
.sweepctl-counts dd { margin: 0; font-size: 20px; color: var(--ink); min-width: 4.6ch; }

.mark { display: inline-block; width: 8px; height: 8px; border-radius: 50%; flex: none; }
.mark.held { background: var(--ink); }
.mark.new { background: transparent; box-shadow: inset 0 0 0 1.5px var(--ink); }

@media (max-width: 560px) { .sweepctl { right: 16px; gap: 12px; } .sweepctl-dial { width: 84px; height: 84px; } }

