              <button role="tab" aria-selected={all} onClick={() => setAll(true)}>Everything</button>
            </div>
            <button className="audit-close" onClick={() => setOpen(false)} aria-label="Close audit"><X size={15} /></button>
          </header>
          <ol className="audit-list">
            {q.isPending && <li className="audit-empty label">Loading…</li>}
            {!q.isPending && rows.length === 0 && <li className="audit-empty label">Nothing recorded here yet.</li>}
            {rows.map((r) => {
              const d = day(r.ts);
              const head = d !== lastDay ? (lastDay = d) : null;
              const text = r.summary ?? line({ action: r.action, stage: r.stage ?? "", payload: r.payload });
              return (
                <li key={r.id} className="audit-row" data-kind={r.kind}>
                  {head && <div className="audit-day label">{head}</div>}
                  <span className="audit-time">{time(r.ts)}</span>
                  <span className="audit-who" data-who={r.actor_type} title={r.model ? `${r.actor} · ${r.model}` : r.actor}>{WHO[r.actor_type] ?? r.actor_type}</span>
                  <span className="audit-text">{text}</span>
                  {r.checkpoint && <span className="audit-cp">{CP_LABEL[r.checkpoint] ?? r.checkpoint}</span>}
                </li>
              );
            })}
          </ol>
          {q.hasNextPage && (
            <button className="audit-more" onClick={() => q.fetchNextPage()} disabled={q.isFetchingNextPage}>
              {q.isFetchingNextPage ? "Loading…" : "Show older"}
            </button>
          )}
        </aside>
      )}
    </>
  );
}
