/* Audit, top-right: a 28px pill like the filter chips that opens the trail, scoped to the current page, in a glass
   sheet like the inspector. Who acted is a quiet tag, never blue (blue is the sweep and the PM's position). */
.audit-btn {
  position: fixed; top: var(--edge); right: var(--edge); z-index: 32; height: 28px; display: inline-flex; align-items: center; gap: 6px;
