  background: rgba(0, 0, 0, 0.6); border: 1px solid var(--hair); transition: color var(--fast), border-color var(--fast), background var(--fast);
}
.audit-btn:hover { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.04); }
.audit-btn[aria-expanded="true"] { color: var(--ink); border-color: var(--hair-2); background: rgba(255, 255, 255, 0.06); }

.audit {
  position: fixed; top: calc(var(--edge) + 40px); right: var(--edge); z-index: 31; width: min(440px, calc(100vw - 32px));
  max-height: calc(100vh - 2 * var(--edge) - 196px); display: grid; grid-template-rows: auto 1fr auto;
  border-radius: var(--r); background: var(--glass); border: 1px solid var(--hair);
  backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.5), 0 24px 60px rgba(0, 0, 0, 0.6); animation: audit-in var(--med) var(--ease);
}
@keyframes audit-in { from { opacity: 0; transform: translateY(-6px); } }
.audit-close { position: absolute; top: 12px; right: 12px; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--ink-3); transition: background var(--fast), color var(--fast); }
.audit-close:hover { background: rgba(255, 255, 255, 0.07); color: var(--ink); }

/* head: layer name, one line on what this view holds, then the scope tabs (filter-tab style) */
.audit-head { display: grid; gap: 6px; padding: 22px 26px 0; }
.audit-layer { display: inline-flex; align-items: center; gap: 8px; font-size: var(--t-label); font-weight: 600; color: var(--ink); padding-right: 28px; }
.audit-layer svg { color: var(--ink-2); }
.audit-what { font-size: var(--t-label); color: var(--ink-3); max-width: 46ch; }
.audit-tabs { display: flex; gap: 16px; margin-top: 8px; border-bottom: 1px solid var(--hair); }
.audit-tabs button { font-size: var(--t-label); color: var(--ink-3); padding: 6px 0; margin-bottom: -1px; border-bottom: 1px solid transparent; transition: color var(--fast), border-color var(--fast); }
.audit-tabs button:hover { color: var(--ink-2); }
.audit-tabs button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--sweep-hi); }

/* rows: time · who · what · checkpoint, grouped under a day line */
.audit-list { list-style: none; margin: 0; padding: 4px 26px 14px; overflow-y: auto; display: grid; align-content: start; }
.audit-row { display: grid; grid-template-columns: 58px 46px 1fr auto; column-gap: 10px; align-items: baseline; padding: 6px 0; font-size: var(--t-label); border-top: 1px solid rgba(255, 255, 255, 0.04); }
.audit-day { grid-column: 1 / -1; padding: 14px 0 6px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }
.audit-row:has(.audit-day) { border-top: 0; }
.audit-time { color: var(--ink-3); font-variant-numeric: tabular-nums; }
.audit-who { justify-self: start; font-size: var(--t-micro); letter-spacing: 0.04em; color: var(--ink-2); padding: 0 5px; border-radius: 4px; box-shadow: inset 0 0 0 1px var(--hair-2); line-height: 17px; }
.audit-who[data-who="human"] { color: var(--void); background: var(--ink); box-shadow: none; }
.audit-who[data-who="system"] { color: var(--ink-3); box-shadow: inset 0 0 0 1px var(--hair); }
.audit-text { color: var(--ink-2); line-height: 1.45; min-width: 0; }
.audit-row[data-kind="run"] .audit-text { color: var(--ink); font-weight: 500; }
.audit-cp { font-size: var(--t-micro); font-weight: 600; color: var(--ink-3); letter-spacing: 0.08em; white-space: nowrap; }
.audit-empty { padding: 18px 0; }
.audit-more { margin: 0 26px 18px; justify-self: start; font-size: var(--t-label); color: var(--ink-2); }
