7	import { useMemo, useRef, type MutableRefObject, type ReactNode } from "react";
8	import { useFrame, type ThreeEvent } from "@react-three/fiber";
9	import { Billboard, Html } from "@react-three/drei";
10	import * as THREE from "three";
11	import type { AreaNode, ClusterNode, Selection, StructurePayload, ThemeNode, TrackState } from "@/lib/types";
12	import type { Hover } from "../scan/Scene";
13	import { TYPE_COLOR } from "../scan/colors";
14	
15	export const AREA_Y = 1.15;
16	const STATE_CODE: Record<TrackState, number> = { held: 0, new: 1, strengthened: 2, weakened: 3, lost: 4 };
17	const SRC_COLOR: Record<string, string> = { research: TYPE_COLOR.research, study: TYPE_COLOR.study, option: TYPE_COLOR.option };
18	
19	const NODE_VERT = /* glsl */ `
20	attribute float aState; attribute float aPol; attribute float aSize; attribute float aIdx;
21	uniform float uScale, uShow, uHover;
22	varying float vState; varying float vPol; varying float vHov;
23	void main() {
24	  vState = aState; vPol = aPol; vHov = abs(aIdx - uHover) < 0.5 ? 1.0 : 0.0;
25	  vec4 mv = modelViewMatrix * vec4(position, 1.0);
26	  gl_Position = projectionMatrix * mv;
27	  gl_PointSize = aSize * uScale * (1.0 + vHov * 0.6) * uShow / -mv.z;
28	}`;
29	const NODE_FRAG = /* glsl */ `
30	uniform float uShow;
31	varying float vState; varying float vPol; varying float vHov;
32	void main() {
33	  vec2 c = gl_PointCoord - 0.5; float r = length(c);
34	  if (r > 0.5) discard;
35	  float dot = smoothstep(0.5, 0.44, r);
36	  float ring = smoothstep(0.5, 0.45, r) * smoothstep(0.34, 0.39, r);
37	  float dbl = ring + smoothstep(0.27, 0.23, r) * smoothstep(0.15, 0.19, r);
38	  float cross = (abs(c.x - c.y) < 0.06 || abs(c.x + c.y) < 0.06) && r < 0.45 ? 1.0 : 0.0;
39	  float a = vState < 0.5 ? dot : vState < 1.5 ? ring : vState < 2.5 ? dbl : vState < 3.5 ? dot : cross;
40	  vec3 base = vPol > 0.5 ? vec3(0.224, 0.529, 0.898) : vec3(0.93, 0.95, 0.97);
41	  vec3 amber = vec3(0.96, 0.65, 0.14);
42	  vec3 col = vState > 2.5 ? amber : base;
43	  col = mix(col, vec3(1.0), vHov);
44	  gl_FragColor = vec4(col, a * uShow * (vState > 3.5 ? 0.8 : 0.95));
45	}`;
