48	function FadeIn({ morph, children }: { morph: MutableRefObject<number>; children: ReactNode }) {
49	  const ref = useRef<THREE.Group>(null);
50	  useFrame(() => {
51	    const g = ref.current;
52	    if (!g) return;
53	    const a = Math.max(0, (morph.current - 0.45) / 0.55);
54	    g.visible = a > 0.01;
55	    g.traverse((o) => {
56	      const mat = (o as THREE.Mesh).material;
