81	export function StructureLayer(p: Props) {
82	  const clusters = useMemo(() => p.data.clusters.filter((c) => c.comments > 0 && !c.tail), [p.data]);
83	  const themeOf = useMemo(() => Object.fromEntries(p.data.themes.map((t) => [t.key, t])), [p.data]);
84	
85	
86	  /* cluster nodes */
87	  const nodeMat = useMemo(() => new THREE.ShaderMaterial({
88	    vertexShader: NODE_VERT, fragmentShader: NODE_FRAG, transparent: true, depthWrite: false,
89	    uniforms: { uScale: { value: 24 * p.dpr }, uShow: { value: 0 }, uHover: { value: -1 } },
90	  }), [p.dpr]);
91	  const nodes = useMemo(() => {
92	    const n = clusters.length;
93	    const pos = new Float32Array(n * 3), st = new Float32Array(n), pol = new Float32Array(n), size = new Float32Array(n), idx = new Float32Array(n);
94	    clusters.forEach((c, i) => {
95	      pos.set([c.x, c.y, c.z], i * 3);
96	      st[i] = STATE_CODE[c.state ?? "held"]; pol[i] = c.polarity === "improve" ? 1 : 0;
97	      size[i] = 1.2 + Math.sqrt(c.comments) * 0.32; idx[i] = i;
98	    });
99	    const g = new THREE.BufferGeometry();
100	    g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
101	    for (const [k, v] of Object.entries({ aState: st, aPol: pol, aSize: size, aIdx: idx })) g.setAttribute(k, new THREE.BufferAttribute(v, 1));
102	    g.computeBoundingSphere();
103	    return g;
104	  }, [clusters]);
105	  nodeMat.uniforms.uHover.value = Math.max(-1, clusters.findIndex((c) => c.key === p.hoverKey));
106	
107	  /* cluster → theme lines */
108	  const memberLines = useMemo(() => {
109	    const v: number[] = [];
110	    for (const c of clusters) {
111	      const t = c.theme ? themeOf[c.theme] : null;
112	      if (t) v.push(c.x, c.y, c.z, t.x, t.y, t.z);
113	    }
114	    return new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(v, 3));
115	  }, [clusters, themeOf]);
116	
117	  /* requirement areas float above the themes they group */
118	  const areas = useMemo(() => {
119	    const out: { a: AreaNode; at: [number, number, number]; ts: ThemeNode[] }[] = [];
120	    for (const a of p.data.areas) {
121	      const ts = a.themes.map((k) => themeOf[k]).filter(Boolean);
122	      if (!ts.length) continue;
123	      const w = ts.reduce((n, t) => n + (t.comments || 1), 0);
124	      const x = ts.reduce((n, t) => n + t.x * (t.comments || 1), 0) / w, z = ts.reduce((n, t) => n + t.z * (t.comments || 1), 0) / w;
125	      out.push({ a, ts, at: [x, a.kind === "quality" ? AREA_Y - 0.35 : AREA_Y, z] });
126	    }
127	    return out;
128	  }, [p.data, themeOf]);
129	  const focusArea = p.selected?.kind === "area" ? p.selected.key : null;
130	  const stems = useMemo(() => {
131	    const v: number[] = [], hot: number[] = [];
132	    for (const { a, at, ts } of areas) for (const t of ts) (a.key === focusArea ? hot : v).push(t.x, t.y, t.z, ...at);
133	    const g = (xs: number[]) => new THREE.BufferGeometry().setAttribute("position", new THREE.Float32BufferAttribute(xs, 3));
134	    return { all: g(v), hot: g(hot) };
135	  }, [areas, focusArea]);
136	
137	  /* evidence arcs for the theme in focus */
138	  const focusTheme = p.selected?.kind === "theme" ? p.selected.key
139	    : p.selected?.kind === "cluster" ? clusters.find((c) => c.key === (p.selected as { key: string }).key)?.theme ?? null
140	    : p.hoverKey && themeOf[p.hoverKey] ? p.hoverKey : null;
141	  const arcs = useMemo(() => {
142	    if (!focusTheme || !themeOf[focusTheme]) return [];
143	    const t = themeOf[focusTheme];
144	    const out: THREE.Line[] = [];
145	    for (const e of p.data.edges) {
146	      if (e.dst_id !== focusTheme || !(e.src_type in SRC_COLOR)) continue;
147	      const end = p.ends(e.src_type, e.src_id);
148	      if (!end) continue;
149	      const a = new THREE.Vector3(t.x, t.y, t.z), b = new THREE.Vector3(...end);
150	      const mid = a.clone().lerp(b, 0.5).add(new THREE.Vector3(0, 0.45 + a.distanceTo(b) * 0.15, 0));
151	      const pts = new THREE.QuadraticBezierCurve3(a, mid, b).getPoints(40);
152	      const geom = new THREE.BufferGeometry().setFromPoints(pts);
153	      const contra = e.relation === "contradicts";
154	      const line = new THREE.Line(geom, contra
155	        ? new THREE.LineDashedMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.7, dashSize: 0.03, gapSize: 0.03 })
156	        : new THREE.LineBasicMaterial({ color: SRC_COLOR[e.src_type], transparent: true, opacity: 0.85 }));
157	      if (contra) line.computeLineDistances();
158	      out.push(line);
159	    }
160	    return out;
161	  }, [focusTheme, themeOf, p.data, p.ends]);
162	
163	  const topThemes = useMemo(() => [...p.data.themes].sort((a, b) => b.comments - a.comments).slice(0, 8).map((t) => t.key), [p.data]);
164	  const pick = (e: ThreeEvent<PointerEvent | MouseEvent>) => e.intersections.find((h) => h.object === e.object && h.index != null)?.index ?? null;
165	
166	  return (
167	    <FadeIn morph={p.morph}>
168	      <lineSegments geometry={memberLines}><lineBasicMaterial color="#ffffff" transparent opacity={0.07} /></lineSegments>
169	      <points geometry={nodes} material={nodeMat}
170	              onPointerMove={(e) => {
171	                const i = pick(e); if (i == null) return;
172	                const c = clusters[i]; e.stopPropagation(); p.setCursor(true);
173	                p.onHover({ title: c.insight?.title ?? c.category ?? "Cluster", sub: `${c.comments} comments · ${c.state ?? ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, c.key);
174	              }}
175	              onPointerOut={() => { p.setCursor(false); p.onHover(null, null); }}
176	              onClick={(e) => { const i = pick(e); if (i == null) return; e.stopPropagation(); const c = clusters[i]; p.onSelect({ kind: "cluster", key: c.key }, [c.x, c.y, c.z]); }} />
177	      {p.data.themes.map((t) => <ThemeHalo key={t.key} t={t} active={t.key === focusTheme} label={topThemes.includes(t.key) || t.key === focusTheme}
178	                                            onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
179	      <lineSegments geometry={stems.all}><lineBasicMaterial color="#ffffff" transparent opacity={0.12} /></lineSegments>
180	      <lineSegments geometry={stems.hot}><lineBasicMaterial color="#ffffff" transparent opacity={0.7} /></lineSegments>
