182	                                         onHover={p.onHover} onSelect={p.onSelect} setCursor={p.setCursor} />)}
183	      {arcs.map((l, i) => <primitive key={`${focusTheme}-${i}`} object={l} />)}
184	    </FadeIn>
185	  );
