195	    <Billboard position={[t.x, t.y, t.z]}>
196	      <mesh onPointerMove={(e) => { e.stopPropagation(); setCursor(true); onHover({ title: t.title, sub: `Theme · ${t.comments} comments${t.state ? ` · ${t.state}` : ""}`, x: e.nativeEvent.clientX, y: e.nativeEvent.clientY }, t.key); }}
197	            onPointerOut={() => { setCursor(false); onHover(null, null); }}
198	            onClick={(e) => { e.stopPropagation(); onSelect({ kind: "theme", key: t.key }, [t.x, t.y, t.z]); }}>
199	        <ringGeometry args={[r, r + (active ? 0.008 : 0.004), 48]} />
200	        <meshBasicMaterial color={lost ? "#f5a524" : "#ffffff"} transparent opacity={active ? 0.95 : changed ? 0.55 : 0.32} depthWrite={false} />
201	      </mesh>
202	      {label && (
203	        <Html position={[0, r + 0.06, 0]} center zIndexRange={[12, 0]}>
