    case "theme": return {
      title: "Theme",
      lead: "Related clusters the AI grouped under one name.",
      uses: "The AI searches research, study and options for evidence and links what it finds; the arcs show those links. Themes are grouped into requirement areas.",
      notes: ["Dashed arc: evidence against the theme."],
    };
    case "area": return {
      title: "Requirement area",
      lead: "A product decision area: themes that belong together, with why it matters now and open questions.",
      uses: "Drafting concrete requirements from an area is the next step; the PM decides, never the AI.",
      notes: ["Blue improve, white keep, orange emerging, amber quality hand-over. Outlined = new at this checkpoint."],
    };
  }
}

function GuideBody({ mode, sel }: { mode: Mode; sel: Selection | null }) {
  const page = sel ? forSelection(sel) : mode === "structure" ? STRUCTURE : SCAN;
  return (
    <div className="guide">
      <p className="guide-title">{page.title}</p>
      {page.lead && <p className="guide-lead">{page.lead}</p>}
      {page.uses && <div className="guide-uses"><span className="label">How the AI uses it</span><p>{page.uses}</p></div>}
      {page.rows && (
        <ul className="guide-rows">
          {page.rows.map((r) => <li key={r.name}><Mark kind={r.mark} /><span><b>{r.name}</b> {r.text}</span></li>)}
        </ul>
      )}
      {page.notes && <ul className="guide-notes">{page.notes.map((n) => <li key={n}>{n}</li>)}</ul>}
    </div>
  );
}

/* ------------------------------------------------------------------------------------------- dock */
const FOLD_KEY = "dock.folded";
const readFold = () => { try { return localStorage.getItem(FOLD_KEY) === "1"; } catch { return false; } };

export function Dock({ mode, sel, agent }: { mode: Mode; sel: Selection | null; agent?: ReactNode }) {
  const [tab, setTab] = useState<"guide" | "agent">(mode === "structure" && agent ? "agent" : "guide");
  const [folded, setFolded] = useState(readFold);
  useEffect(() => { try { localStorage.setItem(FOLD_KEY, folded ? "1" : "0"); } catch { /* private mode */ } }, [folded]);
  useEffect(() => { setTab(mode === "structure" && agent ? "agent" : "guide"); }, [mode]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (sel) setTab("guide"); }, [sel]);      // opening something explains it
  const active = agent ? tab : "guide";
  return (
    <section className="dock" data-folded={folded ? "" : undefined} aria-label="Guide">
      <div className="dock-head">
        <div className="dock-tabs" role="tablist">
          <button role="tab" aria-selected={active === "guide"} onClick={() => { setTab("guide"); setFolded(false); }}>Guide</button>
          {agent && <button role="tab" aria-selected={active === "agent"} onClick={() => { setTab("agent"); setFolded(false); }}>Agent</button>}
        </div>
        <button className="dock-fold" onClick={() => setFolded((f) => !f)} aria-expanded={!folded} aria-label={folded ? "Show" : "Hide"}>
          <ChevronDown size={14} aria-hidden />
        </button>
      </div>
      {!folded && <div className="dock-body">{active === "agent" ? agent : <GuideBody mode={mode} sel={sel} />}</div>}
    </section>
  );
}

